const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const env = typeof $env === 'object' && $env ? $env : {};
const sourcePayload = $json.source_payload_json ?? {};
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const selectedHook = String($json.selected_hook ?? '').trim();
const captionFinal = String($json.caption_final ?? '').trim();
const narrationScript = String($json.narration_script ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Post Asset Item did not produce a valid content_id.');
}
if (!title) {
  throw new Error('Fetch Next Post Asset Item did not produce a title.');
}
if (!selectedHook) {
  throw new Error('Fetch Next Post Asset Item did not produce a selected_hook.');
}
if (!captionFinal) {
  throw new Error('Fetch Next Post Asset Item did not produce caption_final. Run wf_caption_and_hashtags before generating an image.');
}
if (!narrationScript) {
  throw new Error('Fetch Next Post Asset Item did not produce narration_script.');
}
const imageProvider = String(env.POST_IMAGE_PROVIDER || env.IMAGE_GENERATION_PROVIDER || 'openai').trim().toLowerCase() || 'openai';
const imageModel = String(env.POST_IMAGE_MODEL || env.IMAGE_MODEL || env.OPENAI_IMAGE_MODEL || 'gpt-image-1').trim() || 'gpt-image-1';
const imageQuality = String(env.POST_IMAGE_QUALITY || env.IMAGE_QUALITY || env.OPENAI_IMAGE_QUALITY || 'medium').trim().toLowerCase() || 'medium';
const imageSize = String(env.POST_IMAGE_SIZE || env.IMAGE_SIZE || env.OPENAI_IMAGE_SIZE || '1024x1024').trim() || '1024x1024';
const imageStyle = String(env.POST_IMAGE_STYLE || env.IMAGE_STYLE || env.OPENAI_IMAGE_STYLE || 'natural').trim().toLowerCase() || 'natural';
const compressionRaw = Number.parseInt(String(env.POST_IMAGE_COMPRESSION || env.IMAGE_COMPRESSION || env.OPENAI_IMAGE_COMPRESSION || '92').trim(), 10);
const outputCompression = Number.isFinite(compressionRaw) ? Math.max(0, Math.min(100, compressionRaw)) : 92;
const defaultCoverPrompt = String(env.POST_IMAGE_COVER_PROMPT_DIRECTION_DEFAULT || 'Use a cinematic mystery-documentary composition.').trim() || 'Use a cinematic mystery-documentary composition.';
const defaultStyleNotes = String(env.POST_IMAGE_STYLE_NOTES_DEFAULT || 'dark, atmospheric, realistic, cinematic lighting, deep blues, blacks, shadows, mystery and intrigue.').trim() || 'dark, atmospheric, realistic, cinematic lighting, deep blues, blacks, shadows, mystery and intrigue.';
const imageRequest = {
  provider: imageProvider,
  model: imageModel,
  quality: imageQuality,
  size: imageSize,
  style: imageStyle,
  output_format: 'jpeg',
  output_compression: outputCompression,
  n: 1,
};
const rehostPayload = {
  content_id: contentId,
  title,
  category: String($json.category ?? 'general').trim() || 'general',
  selected_hook: selectedHook,
  narration_script: narrationScript,
  cover_prompt: String($json.cover_prompt ?? '').trim() || defaultCoverPrompt,
  style_notes: String($json.style_notes ?? '').trim() || defaultStyleNotes,
  prompt_profile: sourcePayload.prompt_profile ?? {},
  current_status: String($json.status ?? 'storyboard_complete').trim() || 'storyboard_complete',
  caption_final: captionFinal,
  hashtags_final: String($json.hashtags_final ?? '').trim(),
  asset_role: 'post_image',
  workflow_name: 'wf_simple_post_image_asset',
  run_started_at: new Date().toISOString(),
  image_provider: imageProvider,
  image_request: imageRequest,
  openai_image_request: imageRequest,
  storage_public_base_url: String(env.REELS_STORAGE_PUBLIC_BASE_URL || '').trim()
};
return [{
  json: {
    ...rehostPayload,
    rehost_payload_base64: Buffer.from(JSON.stringify(rehostPayload), 'utf8').toString('base64')
  }
}];

const stdout = String($json.stdout ?? '').trim();
if (!stdout) {
  throw new Error('Generate and Rehost Image Asset produced no stdout.');
}
let parsed;
try {
  parsed = JSON.parse(stdout);
} catch (error) {
  throw new Error('Generate and Rehost Image Asset returned invalid JSON: ' + error.message + '. Raw stdout: ' + stdout.slice(0, 500));
}
if (!String(parsed.storage_url ?? '').trim()) {
  throw new Error('The rehost helper did not return storage_url.');
}
if (!String(parsed.provider ?? '').trim()) {
  throw new Error('The rehost helper did not return provider.');
}
if (!String(parsed.mime_type ?? '').trim()) {
  throw new Error('The rehost helper did not return mime_type.');
}
return [{ json: parsed }];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Prepare Asset SQL Values received an invalid content_id: ' + (contentId || '<empty>') + '.');
}
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    asset_role_sql: String($json.asset_role ?? 'post_image').replaceAll("'", "''"),
    provider_sql: String($json.provider ?? 'openai_generated_rehosted_jpeg').replaceAll("'", "''"),
    source_url_sql: String($json.source_url ?? '').replaceAll("'", "''"),
    storage_url_sql: String($json.storage_url ?? '').replaceAll("'", "''"),
    mime_type_sql: String($json.mime_type ?? 'image/jpeg').replaceAll("'", "''"),
    generation_model_sql: String($json.generation_model ?? '').replaceAll("'", "''"),
    asset_validation_note_sql: String($json.asset_validation_note ?? '').replaceAll("'", "''"),
    asset_metadata_json_sql: JSON.stringify($json.asset_metadata_json ?? {}).replaceAll("'", "''"),
    workflow_name_sql: String($json.workflow_name ?? 'wf_simple_post_image_asset').replaceAll("'", "''"),
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0,
    status_sql: 'ready'
  }
}];
